{
  "verse_id": "5.50.1",
  "sarga": 50,
  "verse": "1",
  "ambiguous_marker": false,
  "sanskrit_iast": "tam udvīkṣya mahābāhuḥ piṅgākṣaṃ purataḥ sthitam । roṣeṇa mahatāviṣṭo rāvaṇo lokarāvaṇaḥ ॥1॥",
  "leonov_ru": "Увидя того желтоглазого (Ханумана), стоящего перед ним, мощнорукий Равана, чей рев слышен во всем мире, был охвачен великим гневом.",
  "commentary": {
    "tilaka": "आविष्टः आसीदिति शेषः",
    "bhusana": "तमुद्वीक्ष्य महाबाहुः पिङ्गाक्षं पुरतः स्थितम् ।\n\nकोपेन महता ऽ ऽविष्टो रावणो लोकरावणः\nतमुद्वीक्ष्येत्यादि ।। 5.50.1,2।।\n\nयेन शप्तो ऽस्मि कैलासे मया सञ्चालिते पुरा ।\n\nसो ऽयं वानरमूर्तिः स्यात् किंस्विद्बाणोपि वा ऽसुरः",
    "siromani": "हनुमद्दर्शनानन्तरकालिकं रावणवृत्तान्तमाह तमित्यादिभिः । पिङ्गे अक्षिणी यस्य तं पुरतः स्थितं हनूमन्तम् उद्वीक्ष्य शङ्काहतात्मा शङ्काव्याप्तचित्तः स प्रसिद्धो रावणः दध्यौ चिन्तयामास । सार्धश्लोक एकान्वयी"
  },
  "pratika_check": {
    "tilaka": {
      "pratika_iast": "avistah asiditi sesah",
      "matches_verse": false,
      "content_containment": 0.0
    },
    "bhusana": {
      "pratika_iast": "tanudviksya nahabahuh pingaksan puratah",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "hanunaddarsananantarakalikan ravanavrttantanaha tanityadibhih",
      "matches_verse": true
    }
  }
}

{
  "verse_id": "5.50.34",
  "sarga": 50,
  "verse": "34",
  "ambiguous_marker": false,
  "sanskrit_iast": "",
  "leonov_ru": "",
  "commentary": {
    "bhusana": "बाणः महाबलिसुतः । अनेन तेनापि किञ्चित् शप्तमिति गम्यते । अत्रेतिकरणं द्रष्टव्यम्"
  }
}
{
  "verse_id": "5.50.57",
  "sarga": 50,
  "verse": "57",
  "ambiguous_marker": false,
  "sanskrit_iast": "",
  "leonov_ru": "",
  "commentary": {
    "bhusana": "दुरात्मा पृच्छ्यतामिति । अस्य विवरणम् कुत इत्यादि । कुतः कस्माद्देशादागतः । किं वा ऽस्य कारणम् अस्य कः प्रेरकः । मत्पुरीम्, प्रतीति शेषः । आयोधने युद्धे । किं कार्यं किं प्रयोजनम्"
  }
}
{
  "verse_id": "5.50.89",
  "sarga": 50,
  "verse": "89",
  "ambiguous_marker": false,
  "sanskrit_iast": "",
  "leonov_ru": "",
  "commentary": {
    "bhusana": "यदि तावत्त्वमिन्द्रेणेत्यादि । यदि वैश्रवणस्येत्यादेः दूतो विजकाङ्क्षिणेत्यन्तस्य तत्त्वमाख्याहीति पूर्वेण संबन्धः"
  }
}
{
  "verse_id": "5.50.911",
  "sarga": 50,
  "verse": "911",
  "ambiguous_marker": true,
  "sanskrit_iast": "",
  "leonov_ru": "",
  "commentary": {
    "siromani": "यदीति । यदि वैश्रवणाद्यन्यतमस्य दूतः अत एव प्रेषितस्त्वं नो ऽस्माकं पुरीं प्रविष्टः अथ वा अथापि यन्निमित्तः यदर्थं ते प्रवेशः तच्च तर्हि तत्त्वतः कथयस्व अनृतं वदतस्तव जीवितं जीवनं दुर्लभम् । ननु सामान्यवानर एवाहमित्यत आह वानरं सामान्यवानरसंबन्धि ते तेजो न अद्भुतं तेजो ऽस्तीत्यर्थः, ते रूपमात्रं तु वानरम् । सार्धश्लोकत्रयमेकान्वयि"
  }
}
{
  "verse_id": "5.50.1011",
  "sarga": 50,
  "verse": "1011",
  "ambiguous_marker": true,
  "sanskrit_iast": "",
  "leonov_ru": "",
  "commentary": {
    "bhusana": "न हीत्यादि । अथवेति । यन्निमित्तं कृत्वा ते प्रवेशः तन्निमित्तं कथयस्वेति पूर्वेण संबन्धः"
  }
}

